    INSERT INTO [dbo].[QUESTION] (id, bank_id, type, content, image_url, difficulty, answer) VALUES
    (1, 1, 'MULTIPLE_CHOICE', N'Khi gảy bàn tính Soroban thực hiện phép tính 6 + 2, kết quả chính xác bằng bao nhiêu?
    INSERT INTO [dbo].[QUESTION] (id, bank_id, type, content, image_url, difficulty, answer) VALUES
    (501, 501, 'ESSAY', N'Bài toán suy luận: Bạn An có số kẹo gấp đôi bạn Bình. Nếu An cho Bình 4 chiếc kẹo thì số kẹo hai bạn bằng nhau. Hỏi ban đầu mỗi bạn có bao nhiêu chiếc kẹo? Hãy vẽ sơ đồ đoạn thẳng và trình bày bài giải.', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=600', 'HARD', N'- Hướng dẫn chấm & Lời giải:
